CREATE OR REPLACE SQL SECURITY INVOKER VIEW `valert_map` AS
(select `m`.`id_metric` AS `id_metric`,`m`.`id_dev` AS `id_dev`,`m`.`name` AS `mname`,ifnull(`m`.`label`,`m`.`c_label`) AS `label`,`m`.`type` AS `type`,`m`.`watch` AS `watch`,`a`.`id_alert` AS `id_alert`,`d`.`name` AS `name`,`d`.`domain` AS `domain`,`d`.`ip` AS `ip`,`a`.`cause` AS `cause`,ifnull(`a`.`severity`,0) AS `severity`,ifnull(`a`.`date`,(unix_timestamp(now()) - 86400)) AS `date` from ((`metrics` `m` left join `alerts` `a` on(((`m`.`id_dev` = `a`.`id_device`) and (`m`.`name` = `a`.`mname`)))) left join `devices` `d` on((`d`.`id_dev` = `m`.`id_dev`))) where ((`m`.`watch` <> '0') and (`m`.`type` in ('snmp','xagent')))) union (select `m`.`id_metric` AS `id_metric`,`m`.`id_dev` AS `id_dev`,`m`.`name` AS `mname`,ifnull(`m`.`label`,`m`.`c_label`) AS `label`,`m`.`type` AS `type`,`m`.`watch` AS `watch`,`a`.`id_alert` AS `id_alert`,`d`.`name` AS `name`,`d`.`domain` AS `domain`,`d`.`ip` AS `ip`,`a`.`cause` AS `cause`,ifnull(`a`.`severity`,0) AS `severity`,ifnull(`a`.`date`,(unix_timestamp(now()) - 86400)) AS `date` from ((`metrics` `m` left join `alerts` `a` on(((`m`.`id_dev` = `a`.`id_device`) and (`m`.`name` = `a`.`mname`)))) left join `devices` `d` on((`d`.`id_dev` = `m`.`id_dev`))) where ((`m`.`type` = 'latency') and (`m`.`name` <> 'disp_icmp')));
